require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';$id=trim($_GET['id']??'');$candidate=null;foreach(loadCandidateRecords() as $item)if(($item['id']??'')===$id){$candidate=$item;break;}if(!$candidate){http_response_code(404);exit('Candidate not found.');}$d=candidatePresentation($candidate);$experience=$candidate['experience']??[];$analysis=$candidate['analysis']??[];$skillValues=array_values($experience['skill_months']??[]);$maxSkill=$skillValues?max($skillValues):1;$profiles=db()->prepare('SELECT id,name FROM wishlist_profiles WHERE user_id=? ORDER BY name');$profiles->execute([currentUser()['id']]);$profiles=$profiles->fetchAll();$activePage='candidates';$pageTitle=$d['name'].' · ResumeIQ';$pageStyles='<style>.candidate-head{padding:20px;display:flex;align-items:center;gap:14px}.candidate-head h1{font-size:22px;margin:5px 0}.candidate-head p{font-size:10px;color:var(--muted)}.score-ring{margin-left:auto;width:76px;height:76px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--primary) calc(var(--score)*1%),#eee 0);position:relative}.score-ring:after{content:"";position:absolute;inset:8px;border-radius:50%;background:#fff}.score-ring b{z-index:1}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.detail-panel{padding:18px}.detail-panel h2{font-size:13px;margin:0 0 12px}.pills{display:flex;gap:6px;flex-wrap:wrap}.pill{padding:5px 7px;border-radius:7px;background:var(--green-soft);color:var(--green);font-size:9px}.pill.missing{background:#fff1f3;color:var(--danger)}.timeline{border-left:2px solid #e5dfff;margin-left:5px;padding-left:16px}.event{padding:0 0 15px}.event strong{display:block;font-size:10px}.event span,.muted{font-size:9px;color:var(--muted)}.skill-row{display:grid;grid-template-columns:110px 1fr 45px;gap:8px;align-items:center;margin:9px 0;font-size:9px}.skill-bar{height:7px;background:#eeeef5;border-radius:4px;overflow:hidden}.skill-bar i{display:block;height:100%;background:var(--primary)}.action-row{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:760px){.detail-grid{grid-template-columns:1fr}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="panel candidate-head"><div><a class="muted" href="candidates.php"><i class="fa-solid fa-arrow-left"></i> All candidates</a><h1><?=htmlspecialchars($d['name'])?></h1><p><?=htmlspecialchars($d['role'])?> · <?=htmlspecialchars($candidate['stage']??'Applied')?> · <?=htmlspecialchars($candidate['source']??'Unknown source')?></p></div><div class="score-ring" style="--score:<?=(int)$candidate['score']?>"><b><?=(int)$candidate['score']?>%</b></div></section><section class="panel detail-panel" style="margin-top:10px"><h2>Wishlist, pipeline and email</h2><div class="action-row"><form method="post" action="candidate_wishlist.php" class="action-row"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="candidate_id" value="<?=htmlspecialchars($candidate['id'])?>"><select class="control" name="profile_id" style="width:280px" required><?php foreach($profiles as $profile):?><option value="<?=$profile['id']?>"><?=htmlspecialchars($profile['name'])?></option><?php endforeach?></select><button class="btn btn-primary"><i class="fa-solid fa-heart"></i>Add to wishlist</button></form><a class="btn" href="pipeline.php"><i class="fa-solid fa-table-columns"></i>Pipeline</a><a class="btn" href="wishlist.php"><i class="fa-solid fa-envelope"></i>Email preview</a></div></section><section class="detail-grid"><article class="panel detail-panel"><h2>Strong / matched requirements</h2><div class="pills"><?php foreach($analysis['matched_keywords']??[] as $x):?><span class="pill"><?=htmlspecialchars($x)?></span><?php endforeach?><?php if(empty($analysis['matched_keywords'])):?><p class="muted">No stored matched-keyword evidence.</p><?php endif?></div></article><article class="panel detail-panel"><h2>Missing requirements</h2><div class="pills"><?php foreach($analysis['missing_keywords']??[] as $x):?><span class="pill missing"><?=htmlspecialchars($x)?></span><?php endforeach?><?php if(empty($analysis['missing_keywords'])):?><p class="muted">No stored missing-keyword evidence.</p><?php endif?></div></article><article class="panel detail-panel"><h2>Experience timeline</h2><div class="timeline"><?php foreach($experience['jobs']??[] as $job):?><div class="event"><strong><?=htmlspecialchars(($job['start']??'Unknown').' — '.($job['end']??'Unknown'))?></strong><span><?=round(($job['months']??0)/12,1)?> years · <?=htmlspecialchars(implode(', ',$job['skills']??[]))?></span></div><?php endforeach?><?php if(empty($experience['jobs'])):?><p class="muted">No reliable dated roles detected.</p><?php endif?></div></article><article class="panel detail-panel"><h2>Skill-wise experience</h2><?php foreach($experience['skill_months']??[] as $skill=>$months):?><div class="skill-row"><span><?=htmlspecialchars($skill)?></span><div class="skill-bar"><i style="width:<?=round($months/$maxSkill*100)?>%"></i></div><b><?=round($months/12,1)?>y</b></div><?php endforeach?><?php if(empty($experience['skill_months'])):?><p class="muted">No dated skill tenure evidence.</p><?php endif?><h2 style="margin-top:18px">Employment gaps</h2><?php foreach($experience['gaps']??[] as $gap):?><div class="event"><strong><?=$gap['months']?> months</strong><span><?=htmlspecialchars($gap['after'].' to '.$gap['before'])?></span></div><?php endforeach?><?php if(empty($experience['gaps'])):?><p class="muted">No gap of 2+ months detected.</p><?php endif?></article></section>
